function flattenFields(obj, prefix = '', depth = 0, maxDepth = 3, acc = new Set()) {
  if (!obj || typeof obj !== 'object' || depth > maxDepth) return acc;
  for (const [k, v] of Object.entries(obj)) {
    const fp = prefix ? `${prefix}.${k}` : k; acc.add(fp);
    if (v && typeof v === 'object' && !Array.isArray(v) && !(v instanceof ObjectId) && !(v instanceof Date)) flattenFields(v, fp, depth + 1, maxDepth, acc);
  }
