    (!plan.filter || Object.keys(plan.filter).length === 0)) {
  throw new Error(`${plan.operation} requires a non-empty filter`);
}

if (plan.operation === 'insertOne') {
  const def = previous.schema.collections[plan.collection];
  const required = (def && def.requiredOnCreate) || [];
  const doc = plan.document || {};
  const missing = required.filter(f => doc[f] === undefined || doc[f] === null || doc[f] === '');
  if (missing.length) {
    plan.operation = 'explain';
    plan.missingFields = missing;
    plan.message = `I can create the ${plan.collection} record once you provide: ${missing.join(', ')}.`;
    plan.requiresWrite = false;
  }
