function applyPrivacyProjection(projection, excludeFields) {
  const proj = { ...(projection || {}) };
  const inclusionKeys = Object.keys(proj).filter(k => k !== '_id' && (proj[k] === 1 || proj[k] === true));
  if (inclusionKeys.length > 0) {
    // Inclusion mode: just make sure the sensitive fields are NOT listed.
    // We cannot also add `password:0` because Mongo forbids mixing inclusion and exclusion in one find projection.
    for (const f of excludeFields) {
      if (proj[f] === 1 || proj[f] === true) delete proj[f];
    }
    const stillIncluding = Object.keys(proj).some(k => k !== '_id' && (proj[k] === 1 || proj[k] === true));
    if (!stillIncluding) {
      // The only inclusion was the field we just removed; fall back to exclusion-only mode.
      for (const f of excludeFields) proj[f] = 0;
    }
  } else {
    // Empty {} or pure-exclusion projection: add explicit exclusion.
    for (const f of excludeFields) proj[f] = 0;
  }
  return proj;
}

if (plan.operation === 'find') {
  if (plan.collection === 'users') plan.projection = applyPrivacyProjection(plan.projection, ['password']);
  if (plan.collection === 'chatfiles' || plan.collection === 'homeworkfiles') {
    plan.projection = applyPrivacyProjection(plan.projection, ['data']);
