  for (const [k, v] of Object.entries(value)) {
    if (ARRAY_OPERATORS.has(k)) {
      if (isRefMarker(v)) { out[k] = v; continue; }
      if (v && typeof v === 'object' && !Array.isArray(v)) {
        const innerKeys = Object.keys(v);
        if (innerKeys.length && innerKeys.every(ik => REGEX_LIKE_KEYS.has(ik))) {
          warnings.push(`Auto-fixed: ${k} wrapping around $regex at ${path}; lifted to parent.`);
          out.__liftToParent__ = v;
          continue;
        }
        if (innerKeys.length === 1 && innerKeys[0] === '$eq') {
          warnings.push(`Auto-fixed: ${k} contained $eq at ${path}; converted to array.`);
          out[k] = [v.$eq];
          continue;
        }
        warnings.push(`Suspicious: ${k} value is an object with keys [${innerKeys.join(',')}] at ${path}. Wrapping in array as best-effort.`);
        out[k] = [v];
        continue;
      }
      if (!Array.isArray(v)) {
        warnings.push(`Auto-fixed: ${k} value was a scalar at ${path}; wrapped in array.`);
        out[k] = [v];
        continue;
      }
      out[k] = v.map((item, i) => {
        if (item && typeof item === 'object' && !Array.isArray(item) && !(item instanceof Date)) {
          return sanitizeFilter(item, warnings, `${path}.${k}[${i}]`);
        }
        return item;
      });
      continue;
    }
    if (SCALAR_OPERATORS.has(k)) {
      if (v && typeof v === 'object' && !Array.isArray(v) && !(v instanceof Date) && !isRefMarker(v)) {
        const innerKeys = Object.keys(v);
        if (innerKeys.length === 1 && SCALAR_OPERATORS.has(innerKeys[0])) {
          warnings.push(`Auto-fixed: stripped nested ${innerKeys[0]} inside ${k} at ${path}.`);
          out[k] = v[innerKeys[0]];
          continue;
        }
        if (k === '$eq' && innerKeys.length && innerKeys.every(ik => REGEX_LIKE_KEYS.has(ik))) {
          warnings.push(`Auto-fixed: $eq wrapping $regex at ${path}; lifted to parent.`);
          out.__liftToParent__ = v;
          continue;
        }
      }
      out[k] = v;
      continue;
    }
    out[k] = sanitizeFilter(v, warnings, `${path}.${k}`);
  }

  for (const [fieldName, fieldVal] of Object.entries(out)) {
    if (fieldVal && typeof fieldVal === 'object' && '__liftToParent__' in fieldVal) {
      const lifted = fieldVal.__liftToParent__;
      const rest = { ...fieldVal };
      delete rest.__liftToParent__;
      out[fieldName] = { ...rest, ...lifted };
    }
  }
  return out;
}

function convertObjectIds(value) {
  if (Array.isArray(value)) return value.map(convertObjectIds);
  if (value && typeof value === 'object') {
    if (value instanceof Date) return value;
    if (value._bsontype === 'ObjectID' || value._bsontype === 'ObjectId') return value;
    const out = {};
    for (const [key, val] of Object.entries(value)) {
      if (typeof val === 'string' && /^[a-fA-F0-9]{24}$/.test(val)) out[key] = new ObjectId(val);
      else if (typeof val === 'string' && key === '$date') out[key] = new Date(val);
      else out[key] = convertObjectIds(val);
    }
    return out;
  }
  return value;
}

function sanitizePipeline(pipeline) {
  if (!Array.isArray(pipeline)) return [];
  const blocked = new Set(['$out', '$merge', '$function', '$accumulator']);
  for (const stage of pipeline) {
    const stageName = Object.keys(stage || {})[0];
    if (blocked.has(stageName)) throw new Error(`Blocked unsafe aggregate stage: ${stageName}`);
  }
  return pipeline;
}

async function runPreResolve(db, steps, maxResultLimit) {
  const resolved = {};
  const trace = [];
  for (const step of steps || []) {
    const coll = db.collection(step.collection);
    const limit = Math.min(Number(step.limit || 50), Number(maxResultLimit || 100));
    let docs;
    if (step.operation === 'aggregate') {
      // Substitute $ref placeholders with values resolved by earlier preResolve steps.
      const substitutedPipeline = substituteRefs(step.pipeline || [], resolved);
      const pipeline = convertObjectIds(sanitizePipeline(substitutedPipeline));
      if (!pipeline.some(s => s.$limit)) pipeline.push({ $limit: limit });
      docs = await coll.aggregate(pipeline).toArray();
    } else {
      const substitutedFilter = substituteRefs(step.filter || {}, resolved);
      const filter = convertObjectIds(sanitizeFilter(substitutedFilter, [], `preResolve[${step.as}].filter`));
      let cursor = coll.find(filter);
      if (step.projection && Object.keys(step.projection).length) cursor = cursor.project(step.projection);
      docs = await cursor.limit(limit).toArray();
    }
    let value;
    if (step.extractField) {
      value = docs.map(d => d && d[step.extractField]).filter(v => v !== undefined && v !== null);
    } else {
      value = docs;
    }
    if (step.extractAs === 'first') value = value.length ? value[0] : null;

    const isEmpty = (value === null) || (Array.isArray(value) && value.length === 0);
    if (isEmpty && step.required) {
      const err = new Error(`preResolve "${step.as}" returned no results.`);
      err.userFacing = step.ifEmptyMessage || `No matching ${step.collection} record was found for "${step.as}".`;
      err.preResolveStep = step.as;
      throw err;
    }
    resolved[step.as] = value;
    trace.push({ as: step.as, collection: step.collection, count: Array.isArray(value) ? value.length : (value ? 1 : 0) });
  }
  return { resolved, trace };
}

async function executeMongoPlan(db, plan, maxResultLimit) {
  if (plan.operation === 'explain') {
    return { type: 'message', data: null, message: plan.message || plan.reason || 'The request needs clarification.', preResolveTrace: [] };
  }

  let preResolved = { resolved: {}, trace: [] };
  if (Array.isArray(plan.preResolve) && plan.preResolve.length) {
    preResolved = await runPreResolve(db, plan.preResolve, maxResultLimit);
  }

  const subbed = substituteRefs({
    filter: plan.filter || {},
    document: plan.document || {},
    update: plan.update || {},
    pipeline: plan.pipeline || []
  }, preResolved.resolved);

  const warnings = [];
  const cleanFilter = sanitizeFilter(subbed.filter, warnings, 'filter');
  const cleanUpdate = sanitizeFilter(subbed.update, warnings, 'update');

  const collection = db.collection(plan.collection);
  const filter = convertObjectIds(cleanFilter);
  const update = convertObjectIds(cleanUpdate);
  const document = convertObjectIds(subbed.document);
  const limit = Math.min(Number(plan.options?.limit || 20), Number(maxResultLimit || 100));
  const sort = plan.options?.sort || null;

  const wrap = (extra) => ({ ...extra, preResolveTrace: preResolved.trace, filterWarnings: warnings });

  switch (plan.operation) {
    case 'find': {
      let cursor = collection.find(filter);
      if (plan.projection && Object.keys(plan.projection).length) cursor = cursor.project(plan.projection);
      if (sort && Object.keys(sort).length) cursor = cursor.sort(sort);
      const data = await cursor.limit(limit).toArray();
      return wrap({ type: 'data', data });
    }
    case 'aggregate': {
      const pipeline = convertObjectIds(sanitizePipeline(subbed.pipeline || []));
      if (!pipeline.some(s => s.$limit)) pipeline.push({ $limit: limit });
      const data = await collection.aggregate(pipeline).toArray();
      return wrap({ type: 'data', data });
    }
    case 'insertOne': {
      const result = await collection.insertOne(document);
      return wrap({ type: 'writeResult', data: { acknowledged: result.acknowledged, insertedId: result.insertedId } });
    }
    case 'updateOne': {
      const result = await collection.updateOne(filter, update);
      return wrap({ type: 'writeResult', data: { acknowledged: result.acknowledged, matchedCount: result.matchedCount, modifiedCount: result.modifiedCount, upsertedId: result.upsertedId } });
    }
    case 'updateMany': {
      const result = await collection.updateMany(filter, update);
      return wrap({ type: 'writeResult', data: { acknowledged: result.acknowledged, matchedCount: result.matchedCount, modifiedCount: result.modifiedCount } });
    }
    case 'deleteOne': {
      const result = await collection.deleteOne(filter);
      return wrap({ type: 'writeResult', data: { acknowledged: result.acknowledged, deletedCount: result.deletedCount } });
    }
    case 'deleteMany': {
      const result = await collection.deleteMany(filter);
      return wrap({ type: 'writeResult', data: { acknowledged: result.acknowledged, deletedCount: result.deletedCount } });
    }
    default:
      throw new Error(`Unsupported operation: ${plan.operation}`);
  }
}

const client = new MongoClient($json.config.mongoUri);
try {
  await client.connect();
  const db = client.db($json.config.databaseName);
  try {
    const execution = await executeMongoPlan(db, $json.plan, $json.config.maxResultLimit);
    return [{ json: { ...$json, execution } }];
  } catch (e) {
    if (e && e.userFacing) {
      return [{ json: { ...$json, execution: { type: 'message', data: null, message: e.userFacing, preResolveError: e.message, preResolveStep: e.preResolveStep || null } } }];
    }
    throw e;
  }
} finally {
  await client.close();
}

