 *   - PDF   ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¾ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ real PDF via 'pdfkit' if available, else printable HTML fallback
 *   - Word  ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¾ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ real .docx via 'docx' if available, else HTML-as-DOC fallback
 *
 * To enable real PDF/Excel/Word, set in n8n env:
 *   NODE_FUNCTION_ALLOW_EXTERNAL=pdfkit,xlsx,docx
 */

function toFlatRow(record) {
  const out = {};
  if (record === null || record === undefined) return out;
  if (typeof record !== 'object') return { value: String(record) };
  for (const [k, v] of Object.entries(record)) {
    if (v === null || v === undefined) out[k] = '';
    else if (Array.isArray(v)) out[k] = v.map(x => (x && typeof x === 'object') ? JSON.stringify(x) : String(x)).join('; ');
    else if (typeof v === 'object') {
      if (v._bsontype === 'ObjectID' || v._bsontype === 'ObjectId') out[k] = String(v);
      else if (v instanceof Date) out[k] = v.toISOString();
      else out[k] = JSON.stringify(v);
    }
    else out[k] = v;
  }
  return out;
}

function collectKeys(rows) {
  const keys = []; const seen = new Set();
  for (const r of rows) for (const k of Object.keys(r)) if (!seen.has(k)) { seen.add(k); keys.push(k); }
  return keys;
}

function toCsv(rows) {
  if (!rows.length) return '';
  const keys = collectKeys(rows);
  const esc = v => { const s = v === null || v === undefined ? '' : String(v); return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
  return [keys.map(esc).join(','), ...rows.map(r => keys.map(k => esc(r[k])).join(','))].join('\n');
}

function toHtmlTable(title, rows) {
  if (!rows.length) return `<!doctype html><html><head><meta charset="utf-8"><title>${title}</title></head><body><h2>${title}</h2><p>No records.</p></body></html>`;
  const keys = collectKeys(rows);
  const esc = v => String(v === null || v === undefined ? '' : v).replace(/[&<>]/g, s => ({ '&':'&amp;','<':'&lt;','>':'&gt;' }[s]));
  return `<!doctype html><html><head><meta charset="utf-8"><title>${title}</title>
<style>body{font-family:Arial,sans-serif;padding:24px;color:#222}h2{margin:0 0 16px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{border:1px solid #999;padding:6px 8px;text-align:left;vertical-align:top}th{background:#f0f0f0}tr:nth-child(even){background:#fafafa}@media print{body{padding:8px}}</style>
</head><body><h2>${title}</h2>
<p><strong>Generated:</strong> ${new Date().toISOString()} &nbsp; <strong>Records:</strong> ${rows.length}</p>
<table><thead><tr>${keys.map(k => `<th>${esc(k)}</th>`).join('')}</tr></thead>
<tbody>${rows.map(r => `<tr>${keys.map(k => `<td>${esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table>
<script>setTimeout(()=>{try{window.print()}catch(e){}},250)</script>
</body></html>`;
}

function tryRequire(name) { try { return require(name); } catch (e) { return null; } }

function buildExcel(rows, sheetName) {
  const xlsx = tryRequire('xlsx');
  if (!xlsx) return null;
  const ws = xlsx.utils.json_to_sheet(rows);
  const wb = xlsx.utils.book_new();
  xlsx.utils.book_append_sheet(wb, ws, (sheetName || 'Report').slice(0, 31));
  const buf = xlsx.write(wb, { type: 'buffer', bookType: 'xlsx' });
  return buf;
}

async function buildPdf(title, rows) {
  const PDFDocument = tryRequire('pdfkit');
  if (!PDFDocument) return null;
  return await new Promise((resolve, reject) => {
    try {
      const doc = new PDFDocument({ size: 'A4', margin: 28 });
      const chunks = [];
      doc.on('data', c => chunks.push(c));
      doc.on('end', () => resolve(Buffer.concat(chunks)));
      doc.on('error', reject);
      doc.fontSize(16).text(title, { underline: true });
      doc.moveDown(0.5).fontSize(9).text(`Generated: ${new Date().toISOString()}    Records: ${rows.length}`);
      doc.moveDown(0.5);
      if (!rows.length) { doc.fontSize(10).text('No records.'); doc.end(); return; }
      const keys = collectKeys(rows);
      const colWidth = (doc.page.width - doc.options.margin * 2) / keys.length;
      doc.fontSize(8).fillColor('#000');
      // header
      keys.forEach((k, i) => doc.text(String(k), doc.options.margin + i * colWidth, doc.y, { width: colWidth, continued: i < keys.length - 1 }));
      doc.moveDown(0.2).moveTo(doc.options.margin, doc.y).lineTo(doc.page.width - doc.options.margin, doc.y).stroke();
      // rows
      for (const r of rows) {
        if (doc.y > doc.page.height - 60) doc.addPage();
        const y = doc.y + 2;
        keys.forEach((k, i) => doc.text(String(r[k] ?? ''), doc.options.margin + i * colWidth, y, { width: colWidth, continued: i < keys.length - 1 }));
        doc.moveDown(0.1);
      }
      doc.end();
    } catch (err) { reject(err); }
  });
}

async function buildDocx(title, rows) {
  const docx = tryRequire('docx');
  if (!docx) return null;
  const { Document, Packer, Paragraph, Table, TableRow, TableCell, TextRun, WidthType, HeadingLevel } = docx;
  if (!rows.length) {
    const doc = new Document({ sections: [{ children: [ new Paragraph({ heading: HeadingLevel.HEADING_1, children: [ new TextRun(title) ] }), new Paragraph('No records.') ] }] });
    return await Packer.toBuffer(doc);
  }
  const keys = collectKeys(rows);
  const headerRow = new TableRow({ children: keys.map(k => new TableCell({ children: [ new Paragraph({ children: [ new TextRun({ text: String(k), bold: true }) ] }) ] })) });
  const bodyRows = rows.map(r => new TableRow({ children: keys.map(k => new TableCell({ children: [ new Paragraph(String(r[k] ?? '')) ] })) }));
  const table = new Table({ rows: [headerRow, ...bodyRows], width: { size: 100, type: WidthType.PERCENTAGE } });
  const doc = new Document({ sections: [{ children: [ new Paragraph({ heading: HeadingLevel.HEADING_1, children: [ new TextRun(title) ] }), new Paragraph(`Generated: ${new Date().toISOString()}    Records: ${rows.length}`), table ] }] });
  return await Packer.toBuffer(doc);
}

const intent = $json.intent || {};
const execution = $json.execution || {};
const rawMsg = String($json.message || '').toLowerCase();

function detectFormat() {
  if (intent.exportFormat) return intent.exportFormat;
  if (intent.intentType !== 'report_export' && intent.expectedFormat !== 'download_link') {
    // also detect by keywords for safety
    if (!/\b(export|download|report|pdf|csv|xlsx|excel|word|docx|json file)\b/.test(rawMsg)) return null;
  }
  if (rawMsg.includes('pdf')) return 'pdf';
  if (rawMsg.includes('xlsx') || rawMsg.includes('excel')) return 'excel';
  if (rawMsg.includes('word') || rawMsg.includes('docx') || rawMsg.includes('.doc')) return 'word';
  if (rawMsg.includes('json')) return 'json';
  if (rawMsg.includes('csv')) return 'csv';
  return 'csv';
}

const format = detectFormat();
if (!format || !Array.isArray(execution.data)) {
  return [{ json: { ...$json, exportFile: null } }];
}

const rows = execution.data.map(toFlatRow).slice(0, Number($json.config.exportMaxRows || 5000));
const title = (intent.userGoal || `EduNexus ${$json.plan?.collection || 'report'}`).slice(0, 120);
const safeBase = title.replace(/[^a-z0-9_-]+/gi, '_').slice(0, 60) || 'report';

let result = { format, filename: '', mimeType: '', dataUrl: null, dataLength: 0, fallback: null };

try {
  if (format === 'csv') {
    const csv = toCsv(rows);
    const b64 = Buffer.from(csv, 'utf8').toString('base64');
    result.filename = `${safeBase}.csv`;
    result.mimeType = 'text/csv';
    result.dataUrl = `data:text/csv;base64,${b64}`;
    result.dataLength = csv.length;
  } else if (format === 'json') {
    const json = JSON.stringify(rows, null, 2);
    const b64 = Buffer.from(json, 'utf8').toString('base64');
    result.filename = `${safeBase}.json`;
    result.mimeType = 'application/json';
    result.dataUrl = `data:application/json;base64,${b64}`;
    result.dataLength = json.length;
  } else if (format === 'excel') {
    const buf = buildExcel(rows, safeBase);
    if (buf) {
      const b64 = buf.toString('base64');
      result.filename = `${safeBase}.xlsx`;
      result.mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
      result.dataUrl = `data:${result.mimeType};base64,${b64}`;
      result.dataLength = buf.length;
    } else {
      const csv = toCsv(rows);
      const b64 = Buffer.from(csv, 'utf8').toString('base64');
      result.filename = `${safeBase}.csv`;
      result.mimeType = 'text/csv';
      result.dataUrl = `data:text/csv;base64,${b64}`;
      result.dataLength = csv.length;
      result.fallback = 'xlsx_library_missing_fell_back_to_csv';
    }
  } else if (format === 'pdf') {
    const buf = await buildPdf(title, rows);
    if (buf) {
      const b64 = buf.toString('base64');
      result.filename = `${safeBase}.pdf`;
      result.mimeType = 'application/pdf';
      result.dataUrl = `data:application/pdf;base64,${b64}`;
      result.dataLength = buf.length;
    } else {
      const html = toHtmlTable(title, rows);
      const b64 = Buffer.from(html, 'utf8').toString('base64');
      result.filename = `${safeBase}.html`;
      result.mimeType = 'text/html';
      result.dataUrl = `data:text/html;base64,${b64}`;
      result.dataLength = html.length;
      result.fallback = 'pdfkit_library_missing_returned_printable_html';
    }
  } else if (format === 'word') {
    const buf = await buildDocx(title, rows);
    if (buf) {
      const b64 = buf.toString('base64');
      result.filename = `${safeBase}.docx`;
      result.mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
      result.dataUrl = `data:${result.mimeType};base64,${b64}`;
      result.dataLength = buf.length;
    } else {
      const html = toHtmlTable(title, rows);
      const b64 = Buffer.from(html, 'utf8').toString('base64');
      result.filename = `${safeBase}.doc`;
      result.mimeType = 'application/msword';
      result.dataUrl = `data:application/msword;base64,${b64}`;
