function safeJsonParse(value, fallback = {}) { try { return JSON.parse(value || '{}'); } catch (_) { return fallback; } }
function escapeMarkdownCell(value) {
  if (value === null || value === undefined) return '';
  if (Array.isArray(value)) return value.join(', ').replace(/\|/g, '\\|');
  if (typeof value === 'object') return JSON.stringify(value).replace(/\|/g, '\\|');
  return String(value).replace(/\|/g, '\\|');
}
function recordsToMarkdownTable(records) {
  if (!Array.isArray(records) || records.length === 0) return 'No matching records found.';
  const keys = []; const seen = new Set();
  for (const r of records) { if (!r || typeof r !== 'object') continue; for (const k of Object.keys(r)) if (!seen.has(k)) { seen.add(k); keys.push(k); } }
  const limitedKeys = keys.slice(0, 12);
  if (!limitedKeys.length) return 'No matching records found.';
  const header = `| ${limitedKeys.map(escapeMarkdownCell).join(' | ')} |`;
  const separator = `| ${limitedKeys.map(() => '---').join(' | ')} |`;
  const rows = records.map(record => `| ${limitedKeys.map(k => escapeMarkdownCell(record?.[k])).join(' | ')} |`);
  return [header, separator, ...rows].join('\n');
}
function recordsToBulletList(records) {
  if (!Array.isArray(records) || records.length === 0) return 'No matching records found.';
  return records.map(r => {
    if (r === null || r === undefined) return '-';
    if (typeof r !== 'object') return `- ${String(r)}`;
    const label = r.name || r.title || r.email || r._id || Object.values(r).find(v => typeof v === 'string' || typeof v === 'number') || JSON.stringify(r);
    return `- ${String(label)}`;
  }).join('\n');
}
function buildFallbackAnswer(message, execution, plan, exportFile) {
  if (exportFile && exportFile.dataUrl) {
    const note = exportFile.fallback ? ` _(${exportFile.fallback.replace(/_/g, ' ')})_` : '';
    return `[Download ${exportFile.filename}](${exportFile.dataUrl})${note}`;
  }
  if (execution?.type === 'message') return execution.message || 'Done.';
  const raw = execution?.data;
  if (Array.isArray(raw)) {
    const lower = String(message || '').toLowerCase();
    if (lower.includes('how many') || lower.includes('count')) return String(raw.length);
    if (lower.includes('list') || lower.includes('names')) return recordsToBulletList(raw);
    return recordsToMarkdownTable(raw);
  }
  if (raw && typeof raw === 'object') {
    const parts = [];
    if ('insertedId' in raw) parts.push(`Inserted ID: ${raw.insertedId}`);
    if ('matchedCount' in raw) parts.push(`Matched: ${raw.matchedCount}`);
    if ('modifiedCount' in raw) parts.push(`Modified: ${raw.modifiedCount}`);
    if ('deletedCount' in raw) parts.push(`Deleted: ${raw.deletedCount}`);
    if (parts.length) return parts.join('\n');
  }
  return plan?.reason || 'Done.';
}

