function extractEntities(data, collection) {
  if (!Array.isArray(data)) return [];
  return data.slice(0, 5).map(row => {
    if (!row || typeof row !== 'object') return null;
    const out = { collection };
    if (row._id !== undefined && row._id !== null) out._id = String(row._id);
    for (const key of ['name','title','email','studentId','registrationNumber','employeeId','rollNumber','phone','username']) {
      if (typeof row[key] === 'string') out[key] = row[key];
    }
    if (row.userDoc && typeof row.userDoc === 'object' && row.userDoc.name) out.linkedName = String(row.userDoc.name);
    if (row.studentUser && typeof row.studentUser === 'object' && row.studentUser.name) out.linkedName = String(row.studentUser.name);
    if (row.user && typeof row.user === 'object' && row.user.name) out.linkedName = String(row.user.name);
    return Object.keys(out).length > 1 ? out : null;
  }).filter(Boolean);
}

function shallow(value, maxKeys) {
  if (value === null || value === undefined) return null;
  if (typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.slice(0, maxKeys || 20);
  const out = {};
  const keys = Object.keys(value).slice(0, maxKeys || 20);
  for (const k of keys) {
    const v = value[k];
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      // keep $ref markers literal; truncate other objects to a single level
      if (Object.keys(v).length === 1 && typeof v.$ref === 'string') out[k] = v;
      else out[k] = { ...v };
    } else {
      out[k] = v;
    }
  }
  return out;
}

function compactPlan(plan) {
  if (!plan || typeof plan !== 'object') return null;
  return {
    operation: plan.operation,
    collection: plan.collection,
    document: shallow(plan.document, 30),
    update: shallow(plan.update, 30),
    filter: shallow(plan.filter, 30),
    preResolveSummary: Array.isArray(plan.preResolve) ? plan.preResolve.map(s => ({
      as: s.as,
      collection: s.collection,
      operation: s.operation || 'find',
      filter: shallow(s.filter, 10),
      extractField: s.extractField || null,
      extractAs: s.extractAs || 'array'
    })) : []
  };
}

function extractProvidedFields(plan) {
  if (!plan) return null;
  if (plan.operation === 'insertOne') {
    return plan.document && typeof plan.document === 'object' ? Object.keys(plan.document) : [];
  }
  if (plan.operation === 'updateOne' || plan.operation === 'updateMany') {
    if (plan.update && plan.update.$set && typeof plan.update.$set === 'object') return Object.keys(plan.update.$set);
    return plan.update && typeof plan.update === 'object' ? Object.keys(plan.update) : [];
  }
  return null;
}

